INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6842711, 1029627, 96751, '<td valign="top">I love the textures here, Anita. Still feel that she''s smiling "from the teeth, out"</td>', 'I love the textures here, Anita. Still feel that she''s smiling "from the teeth, out"', '2012-08-16 12:28:27.000000', NULL, 1),
(6842712, 1029548, 96751, '<td valign="top">This looks like a close up of one of those Victoria advertisements. Love the "old" look</td>', 'This looks like a close up of one of those Victoria advertisements. Love the "old" look', '2012-08-16 12:28:56.000000', NULL, 1),
(6842713, 1029376, 96751, '<td valign="top">Wonderful, crooked smile</td>', 'Wonderful, crooked smile', '2012-08-16 12:29:09.000000', NULL, 1),
(6842714, 1029552, 96751, '<td valign="top">That''s a whole lotta trouble right there :-)</td>', 'That''s a whole lotta trouble right there :-)', '2012-08-16 12:29:33.000000', NULL, 1),
(6842717, 1029534, 96751, '<td valign="top">This kid looks like SUCH and instigator :-)  Love the tones, the balance, the perfect moment of plotting</td>', 'This kid looks like SUCH and instigator :-)  Love the tones, the balance, the perfect moment of plotting', '2012-08-16 12:30:12.000000', NULL, 1),
(6842720, 1029535, 96751, '<td valign="top">So, clearly not a smile, and you''re probably getting hammered for it, even though this is precious, and she''s just gorgeous. Tell her that expression will give her wrinkles :-)</td>', 'So, clearly not a smile, and you''re probably getting hammered for it, even though this is precious, and she''s just gorgeous. Tell her that expression will give her wrinkles :-)', '2012-08-16 12:31:06.000000', NULL, 1),
(6842721, 1029489, 96751, '<td valign="top">The teeth make this shot!</td>', 'The teeth make this shot!', '2012-08-16 12:31:41.000000', NULL, 1),
(6842723, 1029345, 96751, '<td valign="top">Pp''g is a bit over the top, but her expression is lovely</td>', 'Pp''g is a bit over the top, but her expression is lovely', '2012-08-16 12:32:12.000000', NULL, 1),
(6842725, 1029488, 96751, '<td valign="top">There''s always one in the back....</td>', 'There''s always one in the back....', '2012-08-16 12:33:31.000000', NULL, 1),
(6842726, 1029253, 96751, '<td valign="top">Lots of work go into these, Lydia! It actually looks like he''s flipping you off :-)  So, what IS the attention span of an amphibian...?</td>', 'Lots of work go into these, Lydia! It actually looks like he''s flipping you off :-)  So, what IS the attention span of an amphibian...?', '2012-08-16 12:34:32.000000', NULL, 1),
(6842727, 1029474, 96751, '<td valign="top">Love the uncle!</td>', 'Love the uncle!', '2012-08-16 12:34:52.000000', NULL, 1),
(6842728, 1029461, 96751, '<td valign="top">She is simply gorgeous - the smile is just too fake for me</td>', 'She is simply gorgeous - the smile is just too fake for me', '2012-08-16 12:35:29.000000', NULL, 1),
(6842974, 1029417, 132898, '<td valign="top">You can see the pool in his eyes....sharp and natural... And water droplets too...very nice</td>', 'You can see the pool in his eyes....sharp and natural... And water droplets too...very nice', '2012-08-16 19:17:38.000000', NULL, 1),
(6842979, 1029410, 132898, '<td valign="top">Love the black and white and the side lighting fading off to black is dramatic...<br/>i find her eyes a bit over white, almost as if light is coming from them...  Might have toned that back a bit, but altogether a very nice image</td>', 'Love the black and white and the side lighting fading off to black is dramatic...i find her eyes a bit over white, almost as if light is coming from them...  Might have toned that back a bit, but altogether a very nice image', '2012-08-16 19:21:41.000000', NULL, 1),
(6842984, 1029535, 132898, '<td valign="top">Great capture...pout like you mean it !</td>', 'Great capture...pout like you mean it !', '2012-08-16 19:23:55.000000', NULL, 1),
(6843060, 1029296, 43463, '<td valign="top">Voted earlier coming back to comment. <br/> <br/>B&amp;W tones are fabulous! Great smiling laugh - it makes me wonder what was so funny to make him crack up with laughter. Wonderful capture of emotion that I am sure will be a treasure in the family album:-) Hope to see this in the top 5.</td>', 'Voted earlier coming back to comment.  B&W tones are fabulous! Great smiling laugh - it makes me wonder what was so funny to make him crack up with laughter. Wonderful capture of emotion that I am sure will be a treasure in the family album:-) Hope to see this in the top 5.', '2012-08-16 22:07:09.000000', NULL, 1),
(6843062, 1029418, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>What a great photo! The smile and the mirth in the eyes makes me think that he is on the edge of breaking out into a joyful laugh. Your B&amp;W tones are fabulously dynamic! Well done all around.</td>', 'Voted earlier coming back to comment. What a great photo! The smile and the mirth in the eyes makes me think that he is on the edge of breaking out into a joyful laugh. Your B&W tones are fabulously dynamic! Well done all around.', '2012-08-16 22:07:31.000000', NULL, 1),
(6843069, 1029157, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>This is the second time viewing and each time I still get the joyful voice in my head, "I got watermelon!". Love her toothy gring:-) Great capture - such a summertime, fun photo. Tis indeed brings back my childhood memories of fun running through sprinklers and eating cool watermelon at my cousin''s house at the height of some scorching summers.</td>', 'Voted earlier coming back to comment. This is the second time viewing and each time I still get the joyful voice in my head, "I got watermelon!". Love her toothy gring:-) Great capture - such a summertime, fun photo. Tis indeed brings back my childhood memories of fun running through sprinklers and eating cool watermelon at my cousin''s house at the height of some scorching summers.', '2012-08-16 22:14:05.000000', NULL, 1),
(6843091, 1029372, 43463, '<td valign="top">First, let me say that your lighting, the model pose, costume and even the backdrop are very well done. It made me call up the picture of the Mona Lisa just to do a side by side comparison. I just love the play of light you captured for it is close to that of Leonardo''s painting. I like how in your capture the clouds form a natural crown/halo around the subject. The smile though like the original is debatable. The left edge of the lips has that Sfumato ''effect'' but the right does not have quite enough of the soft shadows that would balance it out as an elusive soft smile. There is something about the photo that has made me keep coming back to this photo to figure out what strikes me as odd. I think I finally may have figured it out and it rests in the proportions of the lady''s body. The hands appear to be out of proportion to her upper body and head. I think that is an illusion caused by the play of the light AND that the hands are resting more forward away from the body such that they fool my eye into thinking they are a bit larger. That aside, this is a great homage to the original Mona Lisa.</td>', 'First, let me say that your lighting, the model pose, costume and even the backdrop are very well done. It made me call up the picture of the Mona Lisa just to do a side by side comparison. I just love the play of light you captured for it is close to that of Leonardo''s painting. I like how in your capture the clouds form a natural crown/halo around the subject. The smile though like the original is debatable. The left edge of the lips has that Sfumato ''effect'' but the right does not have quite enough of the soft shadows that would balance it out as an elusive soft smile. There is something about the photo that has made me keep coming back to this photo to figure out what strikes me as odd. I think I finally may have figured it out and it rests in the proportions of the lady''s body. The hands appear to be out of proportion to her upper body and head. I think that is an illusion caused by the play of the light AND that the hands are resting more forward away from the body such that they fool my eye into thinking they are a bit larger. That aside, this is a great homage to the original Mona Lisa.', '2012-08-16 22:41:10.000000', NULL, 1),
(6843095, 1029455, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>This photo is all curls, a twinkle in the eyes and a great big sunshine smile. Love the B&amp;W treatment for it allows the emotion to sparkle and shine. Great capture of a happy and very, cute little girl. Well done - I can very well see this in the top 10.</td>', 'Voted earlier coming back to comment. This photo is all curls, a twinkle in the eyes and a great big sunshine smile. Love the B&W treatment for it allows the emotion to sparkle and shine. Great capture of a happy and very, cute little girl. Well done - I can very well see this in the top 10.', '2012-08-16 22:50:07.000000', NULL, 1),
